 import { supabase } from '../lib/supabase';

// Your Yoco Public Key is loaded from .env
const YOCO_PUBLIC_KEY = process.env.REACT_APP_YOCO_PUBLIC_KEY;

// Initialize Yoco SDK (loads only once)
let yocoInstance = null;
const getYoco = () => {
  if (!yocoInstance) {
    if (typeof window.Yoco === 'undefined') {
      console.warn("Yoco SDK not loaded.");
      return null;
    }
    yocoInstance = new window.Yoco({
      key: YOCO_PUBLIC_KEY
    });
  }
  return yocoInstance;
};

// ============================================
// ✅ CORE PAYMENT FUNCTION (Supports Communities & Premium)
// ============================================
export async function initiatePayment({
  amount,
  currency = 'ZAR', // ✅ ALWAYS South African Rands
  email,
  fullName,
  userId,
  communityId = null,
  type = 'community', // 'community' or 'premium'
  metadata = {}
}) {
  try {
    // 1. Calculate fees (70% to creator, 30% to platform)
    const platformFee = type === 'community' ? amount * 0.30 : amount * 0.10;
    const creatorEarnings = type === 'community' ? amount * 0.70 : amount * 0.90;

    // 2. Create pending record in Supabase
    const { data: payment, error } = await supabase
      .from('subscription_payments')
      .insert({
        user_id: userId,
        community_id: communityId,
        amount: amount,
        currency: currency,
        platform_fee: platformFee,
        creator_earnings: creatorEarnings,
        type: type,
        status: 'pending'
      })
      .select()
      .single();

    if (error) throw error;

    // 3. Get Yoco instance
    const yoco = getYoco();
    if (!yoco) {
      throw new Error("Yoco SDK not loaded. Please refresh and try again.");
    }

    // 4. Open Yoco Checkout Popup
    yoco.checkout({
      amount: Math.round(amount * 100), // Yoco expects cents (R50 = 5000)
      currency: currency, // ✅ Forces ZAR
      customer: {
        email: email,
        fullName: fullName || email
      },
      metadata: {
        payment_id: payment.id,
        user_id: userId,
        community_id: communityId,
        type: type,
        ...metadata
      },
      onSuccess: async (result) => {
        console.log('Yoco Payment Successful:', result);
        // Redirect to your success page after payment
        window.location.href = `/payment/success?payment_id=${payment.id}`;
      },
      onClose: () => {
        console.log('Yoco Payment Modal Closed');
      }
    });

    return { success: true, paymentId: payment.id };

  } catch (error) {
    console.error('Yoco payment error:', error);
    return { success: false, error: error.message };
  }
}

// ============================================
// ✅ VERIFY PAYMENT (Called after redirect to /payment/success)
// ============================================
export async function verifyAndCompletePayment(paymentId, userId, communityId = null) {
  try {
    // 1. Update payment status to success
    await supabase
      .from('subscription_payments')
      .update({ status: 'success' })
      .eq('id', paymentId);

    // 2. If it's a community payment, add user as member
    if (communityId) {
      // Check if already member
      const { data: existing } = await supabase
        .from('community_members')
        .select('id')
        .eq('community_id', communityId)
        .eq('user_id', userId)
        .maybeSingle();

      if (!existing) {
        // Add user to community
        await supabase
          .from('community_members')
          .insert({
            community_id: communityId,
            user_id: userId,
            role: 'member',
            status: 'active',
            expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
          });

        // Update member count
        const { data: community } = await supabase
          .from('communities')
          .select('member_count')
          .eq('id', communityId)
          .single();

        await supabase
          .from('communities')
          .update({ member_count: (community?.member_count || 0) + 1 })
          .eq('id', communityId);
      }
    }

    return { success: true };
  } catch (error) {
    console.error('Error completing payment:', error);
    return { success: false, error: error.message };
  }
}
